<?php
require_once __DIR__.'/../includes/bootstrap.php';$admin=require_admin();$db=$GLOBALS['pdo'];$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');$st=$db->prepare('SELECT id,role,is_active FROM users WHERE id=?');$st->execute([$id]);$target=$st->fetch();if(!$target)$error='Akun tidak ditemukan.';elseif((int)$target['id']===(int)$admin['id'])$error='Admin tidak dapat menonaktifkan atau menurunkan peran akunnya sendiri.';elseif($action==='role'){ $role=(string)($_POST['role']??'member');if(!in_array($role,['member','admin'],true))$error='Peran tidak valid.';elseif($target['role']==='admin'&&$role!=='admin'&&(int)$target['is_active']===1&&(int)$db->query('SELECT COUNT(*) FROM users WHERE role="admin" AND is_active=1')->fetchColumn()<=1)$error='Tidak dapat menurunkan satu-satunya admin aktif.';else{$db->prepare('UPDATE users SET role=? WHERE id=?')->execute([$role,$id]);audit_log('admin.user_role_changed','user',(int)$id,['role'=>$role]);$message='Peran akun diperbarui.';}}elseif($action==='status'){ $active=(int)($_POST['is_active']??0)===1?1:0;if(!$active&&$target['role']==='admin'&&(int)$target['is_active']===1&&(int)$db->query('SELECT COUNT(*) FROM users WHERE role="admin" AND is_active=1')->fetchColumn()<=1)$error='Tidak dapat menonaktifkan satu-satunya admin aktif.';else{$db->prepare('UPDATE users SET is_active=? WHERE id=?')->execute([$active,$id]);audit_log($active?'admin.user_activated':'admin.user_suspended','user',(int)$id);$message=$active?'Akun diaktifkan.':'Akun disuspend.';}}else$error='Tindakan tidak dikenali.';}
$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$like='%'.$q.'%';$st=$db->prepare('SELECT COUNT(*) FROM users WHERE name LIKE ? OR email LIKE ?');$st->execute([$like,$like]);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/30));$page=min($page,$pages);$st=$db->prepare('SELECT u.id,u.name,u.email,u.role,u.is_active,u.created_at,u.last_login_at,(SELECT COUNT(*) FROM workspace_members m WHERE m.user_id=u.id) workspace_count,(SELECT COUNT(*) FROM subscriptions s WHERE s.user_id=u.id AND s.status="active") active_subscriptions FROM users u WHERE u.name LIKE ? OR u.email LIKE ? ORDER BY u.created_at DESC LIMIT 30 OFFSET ?');$st->bindValue(1,$like);$st->bindValue(2,$like);$st->bindValue(3,($page-1)*30,PDO::PARAM_INT);$st->execute();$users=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='admin';datanix_header('Admin users','users',$layout);
?>
<div class="admin-kicker">ACCOUNT CONTROL</div><h1 class="admin-page-title">Pengguna</h1><p class="admin-page-desc">Tinjau akun, peran dan status. Password dan kredensial privat tidak pernah ditampilkan.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php elseif($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?>
<form class="admin-filter-row" method="get"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Cari nama atau email"><button class="btn btn-primary btn-sm">Cari</button></form>
<section class="admin-card"><div class="admin-card-head"><strong><?=e(format_number($total))?> akun</strong><span class="admin-badge">Akun aktif <?=e((int)$db->query('SELECT COUNT(*) FROM users WHERE is_active=1')->fetchColumn())?></span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Account</th><th>Role</th><th>Workspaces</th><th>Created / last login</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><strong><?=e($item['name'])?></strong><br><small><?=e($item['email'])?></small></td><td><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=e($item['id'])?>"><input type="hidden" name="action" value="role"><select class="form-select form-select-sm" name="role" <?=((int)$item['id']===(int)$admin['id'])?'disabled':''?>><option value="member" <?=$item['role']==='member'?'selected':''?>>Member</option><option value="admin" <?=$item['role']==='admin'?'selected':''?>>Admin</option></select><?php if((int)$item['id']!==(int)$admin['id']):?><button class="btn btn-light-outline btn-sm">Save</button><?php endif;?></form></td><td><?=e($item['workspace_count'])?> · <?=e($item['active_subscriptions'])?> active plan</td><td><?=e(date('d M Y',strtotime($item['created_at'])))?><br><small><?=e($item['last_login_at']?date('d M Y H:i',strtotime($item['last_login_at'])):'Never signed in')?></small></td><td><span class="admin-badge <?=$item['is_active']?'good':'bad'?>"><?=$item['is_active']?'Active':'Suspended'?></span></td><td><?php if((int)$item['id']!==(int)$admin['id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="user_id" value="<?=e($item['id'])?>"><input type="hidden" name="action" value="status"><input type="hidden" name="is_active" value="<?=$item['is_active']?0:1?>"><button class="btn btn-light-outline btn-sm" data-confirm="<?=$item['is_active']?'Suspend this account?':'Reactivate this account?'?>"><?=$item['is_active']?'Suspend':'Activate'?></button></form><?php else:?><span class="small-muted">Current admin</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><div class="admin-pagination"><span>Page <?=e($page)?> / <?=e($pages)?></span><span><?php if($page>1):?><a class="btn btn-light-outline btn-sm" href="?q=<?=e(rawurlencode($q))?>&amp;page=<?=$page-1?>">← Prev</a><?php endif;?> <?php if($page<$pages):?><a class="btn btn-light-outline btn-sm" href="?q=<?=e(rawurlencode($q))?>&amp;page=<?=$page+1?>">Next →</a><?php endif;?></span></div></section>
